#!/usr/bin/env node
// AUTO-GENERATED OUTPUT, HAND-WRITTEN SCRIPT.
// Reads canonical Markdown from ../ko and ../en (READ-ONLY) and writes Starlight pages into
// src/content/docs/. Never edit src/content/docs by hand: edit the source in ko/ or en/.
// The script adds title/sidebar frontmatter and draft markers only; it never rewrites prose.
//
// Publication rules (see README):
//   - A Korean chapter becomes a page only if its file exists. Chapters that are only
//     registered in content-manifest.json (status "Planned") produce no page.
//   - An English chapter becomes a page only if its file exists AND its manifest status is
//     Reviewed or Published. Nothing else is ever generated under /en/.

import { readFileSync, writeFileSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import {
	REPO_ROOT,
	SITE_ROOT,
	BASE,
	HANDBOOK_TITLE,
	PARTS,
	EXTRA_PAGES,
	EN_RELEASABLE,
	loadManifest,
	fileStem,
	partOf,
	enabledLocales,
} from "../handbook.config.mjs";

const OUT_ROOT = join(SITE_ROOT, "src", "content", "docs");
const entries = loadManifest();
const locales = enabledLocales(entries);

// Visible marker for chapters that exist but are not finished or reviewed.
const STATUS_NOTICE = {
	ko: {
		Draft: {
			badge: "초안",
			banner: "작성 중인 원고입니다. 내용 검토와 수정이 진행 중이며, 최종 승인 및 공개 전 상태입니다.",
		},
		Translated: { badge: "검토 전", banner: "번역 후 아직 검토되지 않은 장입니다." },
		"Needs Update": { badge: "수정 필요", banner: "원본이 바뀌어 수정이 필요한 장입니다." },
	},
	en: {
		Draft: { badge: "Draft", banner: "Work in progress. Review and revision are under way, and this chapter is not yet approved or published." },
		Translated: { badge: "Unreviewed", banner: "Translated but not yet reviewed." },
		"Needs Update": { badge: "Needs update", banner: "The source changed; this chapter needs an update." },
	},
};

function yamlEscape(s) {
	return `"${String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

function yamlLine(key, value, indent) {
	const pad = "  ".repeat(indent);
	if (value === undefined) return null;
	if (Array.isArray(value)) return `${pad}${key}: ${JSON.stringify(value)}`; // JSON is valid YAML
	if (value !== null && typeof value === "object") {
		const nested = Object.entries(value)
			.map(([k, v]) => yamlLine(k, v, indent + 1))
			.filter(Boolean)
			.join("\n");
		return `${pad}${key}:\n${nested}`;
	}
	if (typeof value === "number" || typeof value === "boolean") return `${pad}${key}: ${value}`;
	return `${pad}${key}: ${yamlEscape(value)}`;
}

function writeGenerated(outPath, frontmatter, body) {
	mkdirSync(dirname(outPath), { recursive: true });
	const fm = Object.entries(frontmatter)
		.map(([k, v]) => yamlLine(k, v, 0))
		.filter(Boolean)
		.join("\n");
	const header =
		`---\n${fm}\n---\n` +
		`<!-- AUTO-GENERATED by scripts/sync-content.mjs. Do not edit; edit the source in ko/ or en/ instead. -->\n\n`;
	writeFileSync(outPath, header + body, "utf8");
}

// First "# Title" becomes the page title (Starlight renders the title as the H1).
function extractTitle(md, fallback) {
	const m = md.match(/^#\s+(.+?)\s*$/m);
	if (!m) return { title: fallback, body: md };
	const body = md.slice(0, m.index) + md.slice(m.index + m[0].length);
	return { title: m[1].trim(), body: body.replace(/^\s+/, "") };
}

function sourcePath(locale, chapterId) {
	return join(REPO_ROOT, locale, "chapters", `${fileStem(chapterId)}.md`);
}

function isPublishable(locale, entry) {
	if (!existsSync(sourcePath(locale, entry.chapter_id))) return false;
	if (entry.status === "Planned") return false;
	if (locale === "en") return EN_RELEASABLE.includes(entry.status);
	return true;
}

// Fresh output every run; only this generated directory is ever deleted.
if (existsSync(OUT_ROOT)) rmSync(OUT_ROOT, { recursive: true, force: true });
mkdirSync(OUT_ROOT, { recursive: true });

const generated = { ko: [], en: [] };

for (const locale of locales) {
	let order = 1;
	for (const part of PARTS) {
		for (const chapterId of part.chapters) {
			const entry = entries.find((e) => e.chapter_id === chapterId && e.language === locale);
			const thisOrder = order++;
			if (!entry || !isPublishable(locale, entry)) continue;

			const raw = readFileSync(sourcePath(locale, chapterId), "utf8");
			const { title, body } = extractTitle(raw, entry.title);
			const sidebar = { order: thisOrder };
			const fm = { title, sidebar };
			const notice = STATUS_NOTICE[locale][entry.status];
			if (notice) {
				sidebar.badge = { text: notice.badge, variant: "caution" };
				fm.banner = { content: notice.banner };
			}
			writeGenerated(
				join(OUT_ROOT, locale, "chapters", part.dir, `${fileStem(chapterId).toLowerCase()}.md`),
				fm,
				body
			);
			generated[locale].push(chapterId);
		}
	}
}

// With two locales English is Starlight's default locale (see astro.config.mjs). An English page that
// has no Korean counterpart would make Starlight create a fallback page with English text under /ko/,
// so the build stops instead.
const missingKorean = generated.en.filter((id) => !generated.ko.includes(id));
if (missingKorean.length > 0) {
	console.error(`[sync-content] English chapter(s) ${missingKorean.join(", ")} have no Korean page. Publish the Korean chapter first.`);
	process.exit(1);
}

// ---- workshop materials, reference pages, instructor guide (Korean only) ----------------------
// Copied from ../workshop and ../glossary.md without changing the prose. The instructor guide holds the
// answers: it gets its own group, a gate page, no search indexing and a noindex tag.

const EXTRA_BANNER =
	"초안 (저자 승인 전). 시간 배분은 검증되지 않은 예상이며 실제 학습자 시험은 아직 하지 않았습니다.";
const ANSWERS_BANNER =
	"이 문서에는 실습의 정답과 오류 해설이 들어 있습니다. 학습자는 실습을 마친 뒤에 열어 보세요.";
const extraGenerated = [];
for (const p of EXTRA_PAGES) {
	const srcFile = join(REPO_ROOT, p.src);
	if (!existsSync(srcFile)) continue;
	const { title, body } = extractTitle(readFileSync(srcFile, "utf8"), p.slug);
	const fm = { title, sidebar: { order: p.order }, banner: { content: p.answers ? ANSWERS_BANNER : EXTRA_BANNER } };
	if (p.answers) {
		fm.pagefind = false;
		fm.head = [{ tag: "meta", attrs: { name: "robots", content: "noindex, nofollow" } }];
	}
	writeGenerated(join(OUT_ROOT, "ko", p.dir, `${p.slug}.md`), fm, body);
	extraGenerated.push(p);
}
const hasExtra = (dir) => extraGenerated.some((p) => p.dir === dir);

if (hasExtra("workshop")) {
	writeGenerated(
		join(OUT_ROOT, "ko", "workshop", "index.md"),
		{ title: "실습자료 안내", sidebar: { order: 0 }, banner: { content: EXTRA_BANNER } },
		[
			"6시간 워크숍과 자기 학습에 쓰는 참가자용 자료입니다. 모두 교육용 가상 자료이며 실제 개인정보, 고객정보, 회사 기밀은 들어 있지 않습니다.",
			"",
			"| 자료 | 용도 |",
			"|---|---|",
			"| [참가자 워크북](learner-workbook/) | CH01~CH14 핵심 실습 양식을 하나로 모은 기록 문서 |",
			"| [가상 회의자료](sample-meeting-notes/) | 실습에 입력하는 가상 회의 메모(자료 1~6) |",
			"| [가상 AI 결과물](sample-ai-output/) | 검증 연습용 가상 AI 결과물(실제 AI 출력이 아님) |",
			"| [워크스페이스 양식](workspace-template/) | 최종 구성도와 규칙 묶음 양식 |",
			"",
			"문서 안에 `sample-meeting-notes.md` 같은 파일 이름이 나오면 위 표의 같은 이름 자료를 뜻합니다.",
			"",
			"**정답과 해설은 이 메뉴에 없습니다.** 실습의 정답과 오류 해설은 강사용 안내서에 있으며, 왼쪽 메뉴 맨 아래의 별도 묶음(기본으로 접혀 있음)에 있습니다. 실습을 마치기 전에는 열지 않는 것을 권합니다. 다만 일부 장(CH03, CH06, CH09, CH12)의 본문 6절에는 저자 해설이 함께 실려 있습니다.",
			"",
		].join("\n")
	);
}
if (hasExtra("instructor")) {
	writeGenerated(
		join(OUT_ROOT, "ko", "instructor", "index.md"),
		{
			title: "강사용 안내서: 열기 전에",
			sidebar: { order: 1 },
			banner: { content: ANSWERS_BANNER },
			pagefind: false,
			head: [{ tag: "meta", attrs: { name: "robots", content: "noindex, nofollow" } }],
		},
		[
			"**이 안내서에는 실습의 정답과 오류 해설이 들어 있습니다.** 공개 자료이지만, 학습자가 실습을 하기 전에 정답이 눈에 띄지 않도록 실습자료와 메뉴를 나누고 검색에서 제외했습니다.",
			"",
			"- 학습자: 실습을 마친 뒤에 열어 보세요.",
			"- 강사·진행자: 6시간 및 3시간×2회 운영안, 정답과 해설, 예상 질문, 대체 경로, 완성 수준(Level 1~3) 판정 기준이 들어 있습니다.",
			"",
			"[강사용 안내서 열기](instructor-guide/)",
			"",
		].join("\n")
	);
}

// ---- landing pages -------------------------------------------------------

function koLanding() {
	const lines = [];
	const written = generated.ko.length;
	const total = entries.filter((e) => e.language === "ko").length;
	const core = generated.ko.filter((id) => id.startsWith("AW-CH")).length;
	lines.push(
		`> **개발 중인 초안입니다.** 필수 과정 ${core}개 장의 본문 초안이 있습니다. 초안은 작성 중인 원고이며, 내용 검토와 수정이 진행 중이고, 최종 승인 및 공개 전 상태입니다. 선택·심화 과정은 향후 별도 교육과정으로 개발할 계획이며 지금은 본문이 없습니다.`,
		""
	);
	for (const part of PARTS) {
		lines.push(`### ${part.label.ko}`, "");
		for (const chapterId of part.chapters) {
			const e = entries.find((x) => x.chapter_id === chapterId && x.language === "ko");
			if (!e) continue;
			if (generated.ko.includes(chapterId)) {
				const tag = STATUS_NOTICE.ko[e.status] ? ` _(${STATUS_NOTICE.ko[e.status].badge})_` : "";
				lines.push(`- [${chapterId} · ${e.title}](chapters/${part.dir}/${fileStem(chapterId).toLowerCase()}/)${tag}`);
			} else {
				lines.push(`- ${chapterId} · ${e.title} — 향후 별도 과정 예정`);
			}
		}
		lines.push("");
	}
	return lines.join("\n");
}

function enLanding() {
	const lines = ["Chapters listed here have passed review. Others are not published.", ""];
	for (const part of PARTS) {
		const items = part.chapters.filter((id) => generated.en.includes(id));
		if (items.length === 0) continue;
		lines.push(`### ${part.label.en}`, "");
		for (const chapterId of items) {
			const e = entries.find((x) => x.chapter_id === chapterId && x.language === "en");
			lines.push(`- [${chapterId} · ${e.title}](chapters/${part.dir}/${fileStem(chapterId).toLowerCase()}/)`);
		}
		lines.push("");
	}
	return lines.join("\n");
}

writeGenerated(join(OUT_ROOT, "ko", "index.md"), { title: HANDBOOK_TITLE.ko }, koLanding());
if (locales.includes("en")) {
	writeGenerated(join(OUT_ROOT, "en", "index.md"), { title: HANDBOOK_TITLE.en }, enLanding());
}

// Root page: language entry. Lists only locales that are actually enabled.
const rootLinks = locales.map((l) => `- [${l === "ko" ? "한국어" : "English"}](${BASE}${l}/)`).join("\n");
writeGenerated(
	join(OUT_ROOT, "index.md"),
	{ title: HANDBOOK_TITLE.ko },
	`${HANDBOOK_TITLE.ko} / ${HANDBOOK_TITLE.en}\n\n${rootLinks}\n`
);

console.log(
	`[sync-content] locales=${locales.join(",")} ko_pages=${generated.ko.length} en_pages=${generated.en.length}`
);
